import {
  Button,
  ComboBox as AriaComboBox,
  ComboBoxValue,
  FieldError,
  Group,
  Input,
  Label,
  ListBox,
  ListBoxItem,
  Text,
} from "react-aria-components";
import { PopoverContent } from "./Popover";
import type {
  ComboBoxProps as AriaComboBoxProps,
  ListBoxItemProps,
  ValidationResult,
} from "react-aria-components";
import { Check, ChevronDown } from "./icons";
import type { ReactNode, Ref } from "react";
import { roleSize, type ControlSize } from "./controlSize";
import "./ComboBox.css";

type ComboBoxSize = ControlSize;

type ComboBoxSelectionMode = "single" | "multiple";

/** `selectionMode="multiple"` lets the reader pick several options, as a multiple Select does: the
 *  input stays a search, a line under the field lists what is chosen, and each selected option
 *  carries a check. `value` and `onChange` take a key array in that mode. */
export interface ComboBoxProps<M extends ComboBoxSelectionMode = "single">
  extends Omit<AriaComboBoxProps<object, M>, "className" | "children" | "placeholder"> {
  /**
   * Size axis.
   *
   * @default "medium"
   */
  size?: ComboBoxSize;
  /** Label layout: above the field, or inside it before the input.
   * @default "outside"
   */
  labelPlacement?: "outside" | "inside";
  /** Field label. */
  label?: string;
  /**
   * A `ContextualHelp` shown after the label, for a note the reader opens when they need it rather
   * than a `description` that is always on screen.
   */
  contextualHelp?: ReactNode;
  /** Helper text below the input. */
  description?: string;
  /** Message shown when validation fails. */
  errorMessage?: string | ((v: ValidationResult) => string);
  /** Input placeholder. */
  placeholder?: string;
  /**
   * Content before the input, inside the field: a swatch of the chosen value, a flag, an icon.
   * Muted ink. It is NOT announced with the value, so decorative content should carry `aria-hidden`.
   */
  leading?: ReactNode;
  /** ComboBoxItem list. */
  children?: ReactNode;
  /** Content shown when the list is empty (e.g. no matches after filtering).
      Defaults to a muted "No results found." row. */
  renderEmptyState?: () => ReactNode;
  /** Additional class. sd-combo-box is always retained. */
  className?: string;
  /** Passed to the underlying div DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function ComboBox<M extends ComboBoxSelectionMode = "single">({
  size = "medium",
  labelPlacement = "outside",
  label,
  contextualHelp,
  description,
  errorMessage,
  placeholder,
  leading,
  children,
  renderEmptyState,
  className,
  // react-aria defaults allowsEmptyCollection to false, which CLOSES the popover
  // when nothing matches — so the empty state would never show. Default it on so
  // "No results found." is reachable; consumers can still pass false to opt out.
  allowsEmptyCollection = true,
  ref,
  ...props
}: ComboBoxProps<M>) {
  return (
    <AriaComboBox
      {...props}
      allowsEmptyCollection={allowsEmptyCollection}
      ref={ref}
      className={className ? `sd-combo-box ${className}` : "sd-combo-box"}
    >
      {({ isDisabled }) => {
        /* With the label inside, it opens the field's row as Select's does, and `leading` sits
           between it and the input, beside the value it marks. */
        const field = (
          <Group
            data-size={size}
            data-label-inside={(labelPlacement === "inside" && !!label) || undefined}
            data-leading={leading != null || undefined}
            className="sd-combo-box__group"
          >
            {labelPlacement === "inside" && label && (
              <Label data-label-placement="inside" className={`sd-combo-box__label sd-type-label-${roleSize(size)}`}>
                {label}
              </Label>
            )}
            {leading != null && <span className="sd-combo-box__leading">{leading}</span>}
            <Input
              data-size={size}
              data-follows={(labelPlacement === "inside" && !!label) || leading != null || undefined}
              placeholder={placeholder}
              className={`sd-combo-box__input sd-type-body-${roleSize(size)}`}
            />
            {/* No aria-label here on purpose: RAC's ButtonContext already supplies a
                LOCALIZED name for this trigger (useComboBox → `buttonLabel`) plus an
                aria-labelledby pointing at the field label. A hardcoded string would win
                over the context (local props beat context in useContextProps) and ship
                untranslated English. */}
            <Button data-size={size} className="sd-combo-box__trigger">
              <ChevronDown aria-hidden size="1em" />
            </Button>
          </Group>
        );
        return (
        <>
          {labelPlacement === "outside" && (contextualHelp ? (
            <div className="sd-combo-box__label-group">
              {label && (
                <Label data-disabled={isDisabled || undefined} className={`sd-combo-box__label sd-type-label-${roleSize(size)}`}>
                  {label}
                </Label>
              )}
              {contextualHelp}
            </div>
          ) : (
            label && (
              <Label
                data-disabled={isDisabled || undefined}
                className={`sd-combo-box__label sd-type-label-${roleSize(size)}`}
              >
                {label}
              </Label>
            )
          ))}
          {/* With the label inside, the help trigger sits beside the field on its row: a button
              cannot nest in the field, and alone above it the help would name nothing. */}
          {labelPlacement === "inside" && contextualHelp ? (
            <div className="sd-combo-box__label-group">
              {field}
              {contextualHelp}
            </div>
          ) : (
            field
          )}
          {/* The input is a search in multiple mode, so the choices are named here instead, in the
              list form a multiple Select's trigger uses. Nothing chosen, nothing drawn. */}
          {props.selectionMode === "multiple" && (
            <ComboBoxValue className={`sd-combo-box__value sd-type-body-${roleSize(size)}`} />
          )}
          {description && (
            <Text
              slot="description"
              className={`sd-combo-box__description sd-type-caption-${roleSize(size)}`}
            >
              {description}
            </Text>
          )}
          <FieldError className={`sd-combo-box__error sd-type-caption-${roleSize(size)}`}>
            {errorMessage}
          </FieldError>
          {/* The shared PopoverContent owns the overlay surface (surface small + elevation high).
              The reason for small is the same as Select — this surface contains a **selection
              list**, and list surfaces must use the same tier as Menu. Date/Color families contain
              panels rather than lists, so they retain the medium default.
              ListBox manages role=listbox · roving-tabindex itself → omit Dialog wrapping (noDialog). */}
          <PopoverContent noDialog size="small" matchTriggerWidth>
            <ListBox
              className="sd-combo-box__listbox"
              renderEmptyState={
                renderEmptyState ??
                (() => (
                  <div className="sd-combo-box__empty sd-type-caption-medium">
                    No results found.
                  </div>
                ))
              }
            >
              {children}
            </ListBox>
          </PopoverContent>
        </>
        );
      }}
    </AriaComboBox>
  );
}

export interface ComboBoxItemProps extends Omit<ListBoxItemProps, "className"> {
  /** Optional leading icon, shown before the label. */
  icon?: ReactNode;
  /** Additional class. sd-combo-box__item is always retained. */
  className?: string;
  /** Passed to the underlying option DOM element. */
  ref?: Ref<HTMLDivElement>;
}

export function ComboBoxItem({
  icon,
  className,
  children,
  textValue,
  ...props
}: ComboBoxItemProps) {
  return (
    <ListBoxItem
      {...props}
      // Children render via a function (icon + label), so RAC can't auto-derive textValue —
      // which would break BOTH type-to-select and the ComboBox's own filtering (the default
      // filter matches against textValue). Re-derive from string children (matches
      // ListBoxItem / MenuItem); pass an explicit `textValue` when children aren't plain text.
      textValue={textValue || (typeof children === "string" ? children : undefined)}
      className={
        className
          ? `sd-combo-box__item sd-type-body-medium ${className}`
          : "sd-combo-box__item sd-type-body-medium"
      }
    >
      {(renderProps) => (
        <>
          {icon && (
            <span className="sd-combo-box__item-icon" aria-hidden="true">
              {icon}
            </span>
          )}
          {typeof children === "function" ? children(renderProps) : children}
          {/* Several options can be on at once, so each says so itself, as in a multiple Select.
              Decorative: React Aria exposes the selected state. */}
          {renderProps.selectionMode === "multiple" && renderProps.isSelected && (
            <span className="sd-combo-box__item-check" aria-hidden="true">
              <Check size="1em" />
            </span>
          )}
        </>
      )}
    </ListBoxItem>
  );
}

.sd-combo-box {
  --sd-combo-box-group-background-current: var(--sd-combo-box-group-background);
  display: flex;
  flex-direction: column;
  gap: var(--sd-combo-box-gap);
}
.sd-combo-box[data-readonly] {
  --sd-combo-box-group-background-current: var(--sd-combo-box-group-background-readonly);
}

/* label-group — present only with `contextualHelp`: the label and its help trigger share one row. */
.sd-combo-box__label-group {
  display: flex;
  align-items: center;
  gap: var(--sd-combo-box-label-group-gap);
}

.sd-combo-box__label {
  padding-inline: var(--sd-combo-box-text-padding-inline);
  color: var(--sd-combo-box-label-foreground);
}
.sd-combo-box__label[data-disabled] {
  opacity: var(--sd-state-disabled);
}

.sd-combo-box__group {
  --sd-combo-box-group-radius-current: var(--sd-combo-box-group-radius-medium);
  display: grid;
  grid-template-columns: 1fr auto;
  width: 100%;
  overflow: hidden;
  background: var(--sd-combo-box-group-background-current);
  color: var(--sd-combo-box-group-foreground);
  border: var(--sd-combo-box-group-border-width) solid var(--sd-combo-box-group-border);
  border-radius: var(--sd-combo-box-group-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  transition:
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-combo-box__group[data-hovered] {
  border-color: var(--sd-combo-box-group-border-hover);
}
.sd-combo-box__group[data-focus-within] {
  border-color: var(--sd-combo-box-group-border-focus);
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-combo-box__group[data-invalid] {
  border-color: var(--sd-combo-box-group-border-invalid);
}
.sd-combo-box__group[data-invalid][data-focus-within] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-combo-box-group-border-invalid) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-combo-box__group[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-combo-box__input {
  min-width: 0;
  /* A value wider than the field ends in an ellipsis while it rests, not at a hard clip mid-glyph;
     focused, the input scrolls to the caret as it always has. */
  text-overflow: ellipsis;
  width: 100%;
  background: transparent;
  color: var(--sd-combo-box-input-foreground);
  border: 0;
  outline: 0;
  padding-inline-end: 0;
}
.sd-combo-box__input::placeholder {
  color: var(--sd-combo-box-input-placeholder);
}

.sd-combo-box__group[data-size="x-small"] {
  --sd-combo-box-group-radius-current: var(--sd-combo-box-group-radius-x-small);
  --sd-combo-box-inset-current: var(--sd-combo-box-input-padding-inline-x-small);
  min-height: var(--sd-combo-box-group-height-x-small);
}
.sd-combo-box__group[data-size="small"] {
  --sd-combo-box-group-radius-current: var(--sd-combo-box-group-radius-small);
  --sd-combo-box-inset-current: var(--sd-combo-box-input-padding-inline-small);
  min-height: var(--sd-combo-box-group-height-small);
}
.sd-combo-box__group[data-size="medium"] {
  --sd-combo-box-group-radius-current: var(--sd-combo-box-group-radius-medium);
  --sd-combo-box-inset-current: var(--sd-combo-box-input-padding-inline-medium);
  min-height: var(--sd-combo-box-group-height-medium);
}
.sd-combo-box__group[data-size="large"] {
  --sd-combo-box-group-radius-current: var(--sd-combo-box-group-radius-large);
  --sd-combo-box-inset-current: var(--sd-combo-box-input-padding-inline-large);
  min-height: var(--sd-combo-box-group-height-large);
}
.sd-combo-box__group[data-size="x-large"] {
  --sd-combo-box-group-radius-current: var(--sd-combo-box-group-radius-x-large);
  --sd-combo-box-inset-current: var(--sd-combo-box-input-padding-inline-x-large);
  min-height: var(--sd-combo-box-group-height-x-large);
}
.sd-combo-box__input[data-size="x-small"] {
  padding-inline-start: var(--sd-combo-box-input-padding-inline-x-small);
}
.sd-combo-box__input[data-size="small"] {
  padding-inline-start: var(--sd-combo-box-input-padding-inline-small);
}
.sd-combo-box__input[data-size="medium"] {
  padding-inline-start: var(--sd-combo-box-input-padding-inline-medium);
}
.sd-combo-box__input[data-size="large"] {
  padding-inline-start: var(--sd-combo-box-input-padding-inline-large);
}
.sd-combo-box__input[data-size="x-large"] {
  padding-inline-start: var(--sd-combo-box-input-padding-inline-x-large);
}

/* An inside label and a leading slot open the row before the input: each stands at the input's own
   inset and keeps the group gap after it, so the value they lead starts where it would alone. The
   leading slot after an inside label needs no inset of its own. */
.sd-combo-box__group[data-label-inside],
.sd-combo-box__group[data-leading] {
  grid-template-columns: auto 1fr auto;
  --sd-combo-box-leading-inset-current: var(--sd-combo-box-inset-current);
}
.sd-combo-box__group[data-label-inside] {
  padding-inline-start: var(--sd-combo-box-inset-current);
}
.sd-combo-box__group[data-label-inside][data-leading] {
  grid-template-columns: auto auto 1fr auto;
  --sd-combo-box-leading-inset-current: 0;
}
.sd-combo-box__label[data-label-placement="inside"] {
  align-self: center;
  min-width: 0;
  /* The group pads the input's inset before it (above) and the label's type role adds the text
     inset to that, as a field's text takes it (component-contract.md §6 rule 8); only the gap to
     the value after it is the label's own. */
  padding-inline-end: var(--sd-combo-box-group-gap);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--sd-combo-box-inside-label-foreground);
}
.sd-combo-box__leading {
  display: inline-flex;
  align-items: center;
  padding-inline: var(--sd-combo-box-leading-inset-current) var(--sd-combo-box-group-gap);
  color: var(--sd-combo-box-leading-foreground);
}
.sd-combo-box__input[data-follows] {
  padding-inline-start: 0;
}

.sd-combo-box__trigger {
  /* Resting "chip": the trigger IS a button, so it reads as one at rest — a filled,
     rounded surface inset 4px from the field edges (matching SegmentedControl's inset).
     Hover/pressed darken it via the ::after state-layer; focus ring follows the chip. */
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  /* Square chip — width stated per size, NOT derived.
     `aspect-ratio: 1` would never fire: in a grid the `auto` COLUMN is sized first from the chip's
     intrinsic content (the glyph), and only then does `align-items: stretch` make the height
     definite. Both axes end up definite, and `aspect-ratio` applies only while one is auto, so the
     chip would render as a tall pill, as it would in a flex row.
     The height is the row minus its block inset, so the width says exactly that. */
  /* The UA's own `<button>` padding (`1px 6px` in Chrome) — `reset.css` only normalizes a button's
     font and color, not its box. It was harmless while an explicit width overrode it, but with
     `aspect-ratio` the 6px inline padding widens the chip's intrinsic size and that width transfers
     BACK into the height: at `small` it demanded a 24px chip in a row that only had 22, pushing the
     whole field from 32 to 34 (measured). Literal 0 rather than a token — an explicit "no box of its
     own", not a spacing decision. */
  padding: 0;
  color: var(--sd-combo-box-trigger-foreground);
  border: 0;
  font: inherit;
  cursor: pointer;
  user-select: none;
  background: none;
  /* MARGIN, not padding. Padding moves the glyph inward but leaves the BOX at the full row height,
     and the state layer is `inset: 0` on that box, so hover would paint right up to the field border
     with its square corner clipped by the field's own radius. The chip has to be smaller than the
     row, which only a margin (or a smaller width) can do. The state layer reads
     `border-radius: inherit`, so the chip's radius rounds the tint too. */
  margin: var(--sd-combo-box-trigger-overlay-inset);
  margin-inline-start: 0;
  border-radius: var(--sd-combo-box-trigger-overlay-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  outline: none;
}
/* trigger chevron (size="1em") on the icon scale per size (12/16/20), like every field icon. */
.sd-combo-box__trigger[data-size="x-small"] {
  font-size: var(--sd-combo-box-trigger-icon-size-x-small);
}
.sd-combo-box__trigger[data-size="small"] {
  font-size: var(--sd-combo-box-trigger-icon-size-small);
}
.sd-combo-box__trigger[data-size="medium"] {
  font-size: var(--sd-combo-box-trigger-icon-size-medium);
}
.sd-combo-box__trigger[data-size="large"] {
  font-size: var(--sd-combo-box-trigger-icon-size-large);
}
.sd-combo-box__trigger[data-size="x-large"] {
  font-size: var(--sd-combo-box-trigger-icon-size-x-large);
}
/* hover/pressed via the global state-layer overlay (ADR-0009); pointer-events:none
   so React Aria press/hover pass through. */
/* WCAG 2.2 (2.5.8): guarantee a 24px min pointer target. The chip is sized by the field row, so at
   size=small it is 22 — under the minimum. Transparent overlay, so the painted chip is unchanged;
   inert at medium/large where the chip is already 30/38. Same idiom as Checkbox/Radio/Switch. */
/* Square by construction: the chip's height is the group's content row (its min-height minus
   the two borders) because the grid stretches it, so the WIDTH must state exactly that.
   `aspect-ratio: 1` cannot: a grid sizes the `auto` column from the glyph's intrinsic width FIRST,
   and only then does stretch make the height definite; with both axes definite `aspect-ratio` has
   nothing to derive, and the chip renders as a tall pill. */
.sd-combo-box__trigger[data-size="x-small"] {
  width: calc(var(--sd-combo-box-group-height-x-small) - 2 * var(--sd-combo-box-group-border-width) - 2 * var(--sd-combo-box-trigger-overlay-inset));
}
.sd-combo-box__trigger[data-size="small"] {
  width: calc(var(--sd-combo-box-group-height-small) - 2 * var(--sd-combo-box-group-border-width) - 2 * var(--sd-combo-box-trigger-overlay-inset));
}
.sd-combo-box__trigger[data-size="medium"] {
  width: calc(var(--sd-combo-box-group-height-medium) - 2 * var(--sd-combo-box-group-border-width) - 2 * var(--sd-combo-box-trigger-overlay-inset));
}
.sd-combo-box__trigger[data-size="large"] {
  width: calc(var(--sd-combo-box-group-height-large) - 2 * var(--sd-combo-box-group-border-width) - 2 * var(--sd-combo-box-trigger-overlay-inset));
}
.sd-combo-box__trigger[data-size="x-large"] {
  width: calc(var(--sd-combo-box-group-height-x-large) - 2 * var(--sd-combo-box-group-border-width) - 2 * var(--sd-combo-box-trigger-overlay-inset));
}
.sd-combo-box__trigger::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  translate: -50% -50%;
  min-width: var(--sd-combo-box-trigger-touch-target-size);
  min-height: var(--sd-combo-box-trigger-touch-target-size);
}
.sd-combo-box__trigger::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-combo-box__trigger[data-hovered]::after {
  background: var(--sd-state-hover);
}
.sd-combo-box__trigger[data-pressed]::after {
  background: var(--sd-state-pressed);
}
.sd-combo-box__trigger[data-focus-visible] {
  box-shadow: inset 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-combo-box__trigger[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

/* The chosen options of a multiple ComboBox, unboxed text on the label's line. Empty, it is not drawn. */
.sd-combo-box__value {
  padding-inline: var(--sd-combo-box-text-padding-inline);
  color: var(--sd-combo-box-value-foreground);
}
.sd-combo-box__value[data-placeholder] {
  display: none;
}

.sd-combo-box__description {
  padding-inline: var(--sd-combo-box-text-padding-inline);
  color: var(--sd-combo-box-description-foreground);
}

.sd-combo-box__error {
  padding-inline: var(--sd-combo-box-text-padding-inline);
  color: var(--sd-combo-box-error-foreground);
}

/* popover (overlay) — the floating surface (bg·border·radius·shadow·padding·scroll·motion·
   trigger-width via `matchTriggerWidth`) is owned by the shared PopoverContent (ComboBox.tsx:
   <PopoverContent noDialog>). */

.sd-combo-box__listbox {
  outline: none;
  display: flex;
  flex-direction: column;
}

/* empty state — shown by the ListBox when no options match (renderEmptyState). */
.sd-combo-box__empty {
  padding: var(--sd-combo-box-empty-padding-block) var(--sd-combo-box-empty-padding-inline);
  color: var(--sd-combo-box-empty-foreground);
  text-align: center;
}

.sd-combo-box__item {
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  gap: var(--sd-combo-box-item-gap);
  padding: var(--sd-combo-box-item-padding-block) var(--sd-combo-box-item-padding-inline);
  border-radius: var(--sd-combo-box-item-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  color: var(--sd-combo-box-item-foreground);
  cursor: pointer;
  outline: none;
  /* The hover wash over this part: the surface wash, or over a fill the one named for that fill,
     which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-combo-box-item-state-hover-current: var(--sd-state-hover);
}
/* Interaction state-layer overlay: composites over selected bg (ADR-0009). */
.sd-combo-box__item::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-combo-box__item[data-hovered]::after,
.sd-combo-box__item[data-focused]::after {
  background: var(--sd-combo-box-item-state-hover-current);
}
.sd-combo-box__item[data-selected] {
  background: var(--sd-combo-box-item-background-selected);
  --sd-combo-box-item-state-hover-current: var(--sd-state-hover-selected);
}
.sd-combo-box__item[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

/* The check a selected option carries when several can be chosen, at the trailing edge. */
.sd-combo-box__item-check {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  margin-inline-start: auto;
  font-size: var(--sd-combo-box-item-icon-size);
}

.sd-combo-box__item-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 var(--sd-combo-box-item-icon-size);
  width: var(--sd-combo-box-item-icon-size);
  height: var(--sd-combo-box-item-icon-size);
  font-size: var(--sd-combo-box-item-icon-size);
}
